using FitHub.Domain.Parking;
namespace FitHub.UnitTests;
public sealed class ParkingSpaceTests
{
    [Fact]public void DetectionSupportsEveryOperationalTransition(){var operational=new[]{ParkingState.Available,ParkingState.Occupied,ParkingState.Unknown};foreach(var initial in operational)foreach(var target in operational){var space=new ParkingSpace($"{initial}-{target}","A",initial);var at=space.LastEventAt.AddSeconds(1);var e=space.RecordDetection(target,.82m,"Simulator",at);Assert.Equal(target,space.CurrentState);Assert.Equal(initial,e.PreviousState);Assert.Equal(.82m,e.Confidence);Assert.Equal("Simulator",e.Source);}}
    [Theory][InlineData(ParkingState.Available)][InlineData(ParkingState.Occupied)][InlineData(ParkingState.Unknown)]public void DetectionCannotSetDisabled(ParkingState initial){var x=new ParkingSpace("A","A",initial);Assert.Throws<InvalidOperationException>(()=>x.RecordDetection(ParkingState.Disabled,.9m,"Simulator",x.LastEventAt.AddSeconds(1)));}
    [Theory][InlineData(ParkingState.Available)][InlineData(ParkingState.Occupied)][InlineData(ParkingState.Unknown)]public void DisabledSpaceRejectsDetection(ParkingState target){var x=new ParkingSpace("A","A",ParkingState.Disabled);Assert.Throws<InvalidOperationException>(()=>x.RecordDetection(target,.9m,"Simulator",x.LastEventAt.AddSeconds(1)));}
    [Theory][InlineData(-.01)][InlineData(1.01)]public void DetectionRejectsInvalidConfidence(decimal confidence){var x=new ParkingSpace("A","A");Assert.Throws<ArgumentOutOfRangeException>(()=>x.RecordDetection(ParkingState.Occupied,confidence,"Simulator",x.LastEventAt.AddSeconds(1)));}
    [Fact]public void DetectionRejectsMissingSource(){var x=new ParkingSpace("A","A");Assert.Throws<ArgumentException>(()=>x.RecordDetection(ParkingState.Occupied,.9m,"",x.LastEventAt.AddSeconds(1)));}
    [Fact]public void DetectionRejectsOutOfOrderEvent(){var x=new ParkingSpace("A","A");var at=x.LastEventAt.AddSeconds(2);x.RecordDetection(ParkingState.Occupied,.9m,"Simulator",at);Assert.Throws<InvalidOperationException>(()=>x.RecordDetection(ParkingState.Available,.9m,"Simulator",at.AddSeconds(-1)));}
    [Fact]public void AdministratorCanCorrectEveryTransition(){foreach(var initial in Enum.GetValues<ParkingState>())foreach(var target in Enum.GetValues<ParkingState>()){var x=new ParkingSpace($"{initial}-{target}","A",initial);var e=x.AdministratorCorrect(target,"Manual review",x.LastEventAt.AddSeconds(1),Guid.NewGuid());Assert.Equal(target,x.CurrentState);Assert.Equal(ParkingEventType.AdministratorCorrection,e.EventType);Assert.Equal("Manual review",e.Reason);}}
    [Fact]public void AdministratorCorrectionRequiresReason(){var x=new ParkingSpace("A","A");Assert.Throws<ArgumentException>(()=>x.AdministratorCorrect(ParkingState.Disabled,"",x.LastEventAt.AddSeconds(1),Guid.NewGuid()));}
}
